/* @autogenerated */
import { Component, signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { By } from '@angular/platform-browser';
import { provideNoopAnimations } from '@angular/platform-browser/animations';
import { TranslocoTestingModule } from '@jsverse/transloco';
import { EditableTextComponent } from './editable-text/editable-text.component';
import { EditableChooseComponent } from './editable-choose/editable-choose.component';
import { EditableCheckComponent } from './editable-check/editable-check.component';

const es = {
  common: { hiddenField: 'Campo oculto por permisos' },
  validation: {
    required: 'Este campo es obligatorio',
    minlength: 'Mínimo {{requiredLength}} caracteres',
    invalid: 'El valor no es válido',
  },
  user: {
    name: { label: 'Nombre', hint: 'Como aparece en el DNI', error: { required: 'El nombre es obligatorio' } },
    kind: { label: 'Tipo' },
    active: { label: 'Activo' },
  },
};

@Component({
  imports: [ReactiveFormsModule, EditableTextComponent, EditableChooseComponent, EditableCheckComponent],
  template: `
    <form [formGroup]="form">
      <editable-text
        formControlName="name"
        label="user.name"
        [visible]="visible()"
        [showHiddenMark]="true"
        appearance="fill"
      />
      <editable-choose formControlName="kind" label="user.kind" [options]="['a', 'b']" />
      <editable-check formControlName="active" label="user.active" />
    </form>
  `,
})
class HostComponent {
  visible = signal(true);
  form = new FormGroup({
    name: new FormControl<string | null>(null, [Validators.required, Validators.minLength(8)]),
    kind: new FormControl<string | null>(null),
    active: new FormControl<boolean>(false),
  });
}

describe('BaseEditable', () => {
  afterEach(() => TestBed.resetTestingModule());

  function setup() {
    TestBed.configureTestingModule({
      imports: [
        HostComponent,
        TranslocoTestingModule.forRoot({
          langs: { es },
          translocoConfig: { availableLangs: ['es'], defaultLang: 'es' },
          preloadLangs: true,
        }),
      ],
      providers: [provideNoopAnimations()],
    });
    const fixture = TestBed.createComponent(HostComponent);
    fixture.detectChanges();
    const text = fixture.debugElement.query(By.directive(EditableTextComponent)).componentInstance;
    return { fixture, host: fixture.componentInstance, text: text as EditableTextComponent };
  }

  it('aplica el valor y el estado de inmediato, sin esperar un tick', () => {
    const { host, text } = setup();

    host.form.patchValue({ name: 'Ana' });
    expect((text as any).value()).toBe('Ana');
    host.form.patchValue({ name: 'Eva' });
    expect((text as any).value()).toBe('Eva');

    host.form.controls.name.disable();
    expect((text as any).disabled()).toBeTrue();
  });

  it('detecta required con hasValidator y lo recalcula al cambiar los validadores', () => {
    const { host, text } = setup();
    expect(text.required()).toBeTrue();

    host.form.controls.name.setValidators(Validators.maxLength(3));
    host.form.controls.name.updateValueAndValidity();
    expect(text.required()).toBeFalse();
  });

  it('expone los errores con sus parámetros', () => {
    const { host, text } = setup();
    host.form.patchValue({ name: 'corto' });

    expect(text.errorList()).toEqual([{ key: 'minlength', params: { requiredLength: 8, actualLength: 5 } }]);
  });

  it('usa la traducción del campo y, si no existe, la común de validation', () => {
    const { text } = setup();

    expect(text.errorKey({ key: 'required', params: {} })).toBe('user.name.error.required');
    expect(text.errorKey({ key: 'minlength', params: {} })).toBe('validation.minlength');
    expect(text.errorKey({ key: 'name.required', params: {} })).toBe('validation.required');
    expect(text.errorKey({ key: 'custom', params: {} })).toBe('validation.invalid');
  });

  it('pinta "Mínimo 8 caracteres" sin traducción específica del campo', () => {
    const { fixture, host } = setup();
    host.form.controls.name.setValue('corto');
    host.form.controls.name.markAsTouched();
    fixture.detectChanges();

    const error = fixture.nativeElement.querySelector('editable-text mat-error');
    expect(error.textContent.trim()).toBe('Mínimo 8 caracteres');
  });

  it('pinta los errores en el pie del campo y solo después de tocarlo', () => {
    const { fixture, host } = setup();
    const field: HTMLElement = fixture.nativeElement.querySelector('editable-text');
    expect(field.querySelector('mat-error')).toBeNull();

    host.form.controls.name.markAsTouched();
    fixture.detectChanges();

    expect(field.querySelector('.mat-mdc-form-field-subscript-wrapper mat-error')).not.toBeNull();
    expect(field.querySelector('.mat-mdc-form-field-infix mat-error')).toBeNull();
  });

  it('pinta label, ayuda y apariencia a través del envoltorio', () => {
    const { fixture } = setup();
    const field: HTMLElement = fixture.nativeElement.querySelector('editable-text');

    expect(field.classList).toContain('editable');
    expect(field.querySelector('mat-label')?.textContent?.trim()).toBe('Nombre');
    expect(field.querySelector('mat-hint')?.textContent?.trim()).toBe('Como aparece en el DNI');
    expect(field.querySelector('.mat-form-field-appearance-fill')).not.toBeNull();
    expect(field.querySelector('input')?.classList).toContain('mat-mdc-form-field-input-control');
    // Sin `<label>.hint` no hay ayuda
    expect(fixture.nativeElement.querySelector('editable-choose mat-hint')).toBeNull();
  });

  it('anuncia los campos ocultos por permisos', () => {
    const { fixture, host } = setup();
    host.visible.set(false);
    fixture.detectChanges();

    const mark = fixture.nativeElement.querySelector('editable-text editable-hidden-mark [role="img"]');
    expect(mark.getAttribute('aria-label')).toBe('Nombre: Campo oculto por permisos');
    expect(fixture.nativeElement.querySelector('editable-text input')).toBeNull();
  });

  it('pinta los controles sin mat-form-field en modo bare', () => {
    const { fixture } = setup();
    const check: HTMLElement = fixture.nativeElement.querySelector('editable-check');

    expect(check.querySelector('mat-checkbox')?.textContent?.trim()).toBe('Activo');
    expect(check.querySelector('mat-form-field')).toBeNull();
  });
});
